package com.careflow.hospital.doctors;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="doctor") public class Doctor {@Id @Column(name="doctor_id")private UUID id;@Column(name="user_id",nullable=false,unique=true)private UUID userId;@Column(name="doctor_number",nullable=false,unique=true)private String doctorNumber;@Column(name="department_id",nullable=false)private UUID departmentId;@Column(name="verification_status",nullable=false)private String verificationStatus;@Column(nullable=false)private boolean active;@Column(name="full_name",nullable=false)private String fullName;@Column(nullable=false)private String specialization;@Column(name="license_number",unique=true)private String licenseNumber;@Column(name="experience_years",nullable=false)private int experienceYears;protected Doctor(){}public Doctor(DoctorApplication a){id=UUID.randomUUID();userId=a.getUserId();doctorNumber="DOC-"+id.toString().substring(0,8).toUpperCase(Locale.ROOT);departmentId=a.getDepartmentId();verificationStatus="APPROVED";active=true;fullName=a.getFullName();specialization=a.getSpecialization();licenseNumber=a.getLicenseNumber();experienceYears=a.getExperienceYears();}public UUID getId(){return id;}public UUID getUserId(){return userId;}public String getDoctorNumber(){return doctorNumber;}public UUID getDepartmentId(){return departmentId;}public String getVerificationStatus(){return verificationStatus;}public String getFullName(){return fullName;}public String getSpecialization(){return specialization;}public String getLicenseNumber(){return licenseNumber;}public int getExperienceYears(){return experienceYears;}public boolean isActive(){return active;}}
